def close_current_season(apps, schema_editor):
    """Everything logged so far becomes one finished season. The site is
    between seasons when this ships, so hours start out read-only until an
    admin opens the next season."""
    HoursSeason = apps.get_model('hours_app', 'HoursSeason')
    HoursSeasonTotal = apps.get_model('hours_app', 'HoursSeasonTotal')
    CheckInOut = apps.get_model('hours_app', 'CheckInOut')
    SeasonRank = apps.get_model('hours_app', 'SeasonRank')
    if HoursSeason.objects.exists():
        return
    now = timezone.now()
    first = CheckInOut.objects.exclude(check_in_time__isnull=True).order_by('check_in_time').first()
    CheckInOut.objects.filter(check_out_time__isnull=True).update(check_out_time=now)
    season = HoursSeason.objects.create(
        name='2025–2026 Season',
        started_at=first.check_in_time if first else now,
        ended_at=now,
    )
    for rank in SeasonRank.objects.all():
        HoursSeasonTotal.objects.create(season=season, user_id=rank.user_id, total_hours=rank.total_hours)


